let data = msg.payload;

if(data.status == "deployed"){

    // Ejemplo: regla simple
    if (data.spl_db > 150 && data.snr_db > 20) {
        data.status = "ALERT";
    } else if (data.spl_db > 120) {
        data.status = "WARNING";
    } else {
        data.status = "OK";
    }

    // Devuelve el JSON modificado
    msg.payload = {
        id: data.id,
        lat: data.lat,
        lon: data.lon,
        temp_c: data.temp_c,
        sal_psu: data.sal_psu,
        pressure_dbar: data.pressure_dbar,
        depth_m: data.depth_m,
        dom_freq_hz: data.dom_freq_hz,
        spl_db: data.spl_db,
        snr_db: data.snr_db,
        batt_pct: data.batt_pct,
        rssi_dbm: data.rssi_dbm,
        status: data.status
    };
}


return msg;

function rand(base, delta, decimals = 2) {
    const v = base + (Math.random() * 2 - 1) * delta;
    return Number(v.toFixed(decimals));
}

